package com.bank.oracle.model;

import com.bank.oracle.convert.BooleanToNumberConverter;
import jakarta.persistence.*;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "accounts")
public class Account {

    // MIGRATION: IDENTITY (MySQL AUTO_INCREMENT) → SEQUENCE (Oracle sequence object)
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "account_seq_gen")
    @SequenceGenerator(name = "account_seq_gen", sequenceName = "account_seq", allocationSize = 50)
    private Long id;

    @Column(name = "holder_name", nullable = false, length = 100)  // → VARCHAR2(100)
    private String holderName;

    @Column(nullable = false, precision = 15, scale = 2)           // → NUMBER(15,2)
    private BigDecimal balance;

    // boolean → NUMBER(1) via converter (no native Oracle boolean pre-23c)
    @Convert(converter = BooleanToNumberConverter.class)
    @Column(nullable = false)
    private boolean active;

    @Lob
    @JdbcTypeCode(SqlTypes.CLOB)                                    // → CLOB (was TEXT)
    private String notes;

    @Column(name = "created_at", nullable = false, updatable = false) // → TIMESTAMP
    private LocalDateTime createdAt;

    protected Account() {}

    public Account(String holderName, BigDecimal balance, boolean active, String notes) {
        this.holderName = holderName;
        this.balance = balance;
        this.active = active;
        this.notes = notes;
        this.createdAt = LocalDateTime.now();
    }

    public Long getId() { return id; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public boolean isActive() { return active; }
    public String getNotes() { return notes; }
}
