package com.bank.oracle.service;

import com.bank.oracle.dto.MigrationNote;
import com.bank.oracle.model.Account;
import com.bank.oracle.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountService {

    private final AccountRepository accountRepo;

    @Transactional
    public MigrationNote open(String holderName, BigDecimal balance, String notes) {
        Account account = new Account(holderName, balance, true, notes);
        accountRepo.save(account);
        // Oracle sequence assigned the id (SELECT account_seq.NEXTVAL); batching now possible
        log.info("Opened account id={} via SEQUENCE (Oracle), balance NUMBER(15,2)", account.getId());
        return new MigrationNote(account.getId(), List.of(
            "dialect: MySQLDialect → OracleDialect",
            "driver/url: mysql Connector/J → ojdbc thin (1521/service)",
            "id gen: IDENTITY (AUTO_INCREMENT) → SEQUENCE (account_seq, batchable)",
            "types: VARCHAR→VARCHAR2, DECIMAL→NUMBER(15,2), BOOLEAN→NUMBER(1), TEXT→CLOB",
            "semantics: Oracle empty-string = NULL; identifiers UPPERCASE unless quoted"));
    }

    @Transactional(readOnly = true)
    public Account view(Long id) {
        return accountRepo.findById(id).orElseThrow();
    }
}
