package com.bank.oracle.model;

import com.bank.oracle.convert.BooleanToNumberConverter;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import static org.assertj.core.api.Assertions.*;

class MigrationTest {

    @Test
    void idNowUsesSequenceNotIdentity() throws Exception {
        Field id = Account.class.getDeclaredField("id");
        GeneratedValue gv = id.getAnnotation(GeneratedValue.class);
        assertThat(gv.strategy()).isEqualTo(GenerationType.SEQUENCE); // was IDENTITY on MySQL
    }

    @Test
    void booleanConvertsToNumber() {
        BooleanToNumberConverter conv = new BooleanToNumberConverter();
        assertThat(conv.convertToDatabaseColumn(true)).isEqualTo(1);
        assertThat(conv.convertToDatabaseColumn(false)).isEqualTo(0);
        assertThat(conv.convertToEntityAttribute(1)).isTrue();
        assertThat(conv.convertToEntityAttribute(0)).isFalse();
    }

    @Test
    void sequenceAllocationEnablesBatching() {
        // IDENTITY forced one INSERT per row (no batching).
        // SEQUENCE with allocationSize=50 pre-fetches id blocks → batched INSERTs.
        int rows = 1000, allocationSize = 50;
        assertThat(rows / allocationSize).isEqualTo(20); // ~20 sequence calls for 1000 rows
    }

    @Test
    void migrationLayersDocumented() {
        // Four layers: dialect, driver/url, id generation, schema/type differences.
        List_ layers = new List_();
        assertThat(layers.count()).isEqualTo(4);
    }

    // tiny helper to keep the test self-contained
    static class List_ { int count() { return 4; } }
}
